  "vconcat": [
    {
      "height": 2000,
      "weigh"
      "hconcat": [
        {
          "title": "职位平均薪资 Top 10",
          "data": { "url": "/ds_salaries.csv" },
          "transform": [
            {
              "aggregate": [{"op": "mean", "field": "salary_in_usd", "as": "avg_salary"}],
              "groupby": ["job_title"]
            },
            {
              "window": [{"op": "rank", "as": "rank"}],
              "sort": [{"field": "avg_salary", "order": "descending"}]
            },
            {
              "filter": "datum.rank <= 10"
            }
          ],
          "mark": "bar",
          "encoding": {
            "y": {"field": "job_title", "type": "nominal", "sort": "-x", "title": "职位"},
            "x": {"field": "avg_salary", "type": "quantitative", "title": "平均薪资(USD)"},
            "tooltip": [
              {"field": "job_title", "type": "nominal", "title": "职位"},
              {"field": "avg_salary", "type": "quantitative", "title": "平均薪资"}
            ]
          }
        },
        {
          "title": "经验水平与薪资分布",
          "mark": "boxplot",
          "height": 200,
          "data": { "url": "/ds_salaries.csv" },
          "encoding": {
            "x": { "field": "experience_level", "type": "nominal", "title": "经验水平" },
            "y": { "field": "salary_in_usd", "type": "quantitative", "title": "薪资(USD)" },
            "color": { "field": "experience_level", "type": "nominal", "legend": null }
          }
        }
      ]
    },
    {
      "hconcat": [
        {
          "title": "远程占比与距离",
          "mark": "line",
          "height": 200,
          "data": { "url": "/ds_salaries.csv" },
          "encoding": {
            "x": { "field": "remote_ratio", "type": "ordinal", "title": "远程工作比例" },
            "y": { "aggregate": "mean", "field": "salary_in_usd", "type": "quantitative", "title": "平均薪资(USD)" }
          }
        },
        {
          "title": "公司规模与平均薪资关系",
          "mark": "bar",
          "height": 200,
          "data": { "url": "/ds_salaries.csv" },
          "encoding": {
            "x": { "field": "company_size", "type": "ordinal", "title": "公司规模" },
            "y": { "aggregate": "mean", "field": "salary_in_usd", "type": "quantitative", "title": "平均薪资(USD)" },
            "color": { "field": "company_size", "type": "nominal", "legend": null }
          }
        },
        {
          "title": "薪资和职位、经验等级的关系",
          "mark": "bar",
          "height": 100,
          "data": { "url": "/ds_salaries.csv" },
          "encoding": {
            "x": {
              "field": "job_title",
              "type": "nominal",
              "sort": "-x",
              "title": "职位"
            },
            "y": {
              "aggregate": "avg",
              "field": "salary_in_usd",
              "type": "quantitative",
              "title": "平均薪资 (USD)"
            },
            "color": {
              "field": "experience_level",
              "type": "nominal",
              "title": "经验水平"
            },
            "tooltip": [
              {"field": "job_title", "type": "nominal", "title": "职位"},
              {"field": "experience_level", "type": "nominal", "title": "经验水平"},
              {"aggregate": "avg", "field": "salary_in_usd", "type": "quantitative", "title": "平均薪资"}
            ]
          }
        }
      ]
    }
  ]
}

